.ds {
  --ds-bg:var(--p-bg,#ffffff);
  --ds-surface:var(--p-surface,#f1f3f6);
  --ds-high:var(--p-high,#fafbfc);
  --ds-text:var(--p-ink,#2c333d);
  --ds-muted:var(--p-muted,#59636f);
  --ds-border:var(--p-line,#c2cad5);
  --ds-control-border:var(--p-control-border,#7b8592);
  --ds-soft:var(--p-soft,#d3e8de);
  --ds-accent:var(--p-accent,#303b48);
  --ds-on-accent:var(--p-on-accent,#ffffff);
  --ds-focus:var(--p-highlight,#6153b5);
  --ds-error:var(--p-error,#a3313e);
  --ds-success:var(--p-success,#26614f);
  --ds-warning:var(--p-warning,#805719);
  --ds-radius:var(--p-radius,24px);
  --ds-control-radius:var(--p-control-radius,16px);
  --ds-shadow:var(--p-shadow,6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed);
  --ds-raised:var(--p-raised,3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed);
  --ds-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-glass:var(--p-glass,#f6f8fbe8);
  --ds-disabled:var(--p-disabled,#dce1e8);
  --ds-duration:var(--p-duration,140ms);
  --ds-font:var(--p-font,Pretendard, sans-serif);
  --ds-display-font:var(--p-display-font,Outfit, Pretendard, sans-serif);
  --ds-text-sm:var(--p-text-sm,13px);
  --ds-text-md:var(--p-text-md,16px);
  --ds-text-lg:var(--p-text-lg,24px);
  --ds-space-2:var(--p-space-xs,8px);
  --ds-space-3:var(--p-space-sm,12px);
  --ds-space-4:var(--p-space-md,16px);
  --ds-space-6:var(--p-space-lg,24px);
  --ds-space-8:var(--p-space-xl,32px);
}
.ds {
  color:var(--ds-text); background:var(--ds-bg); font:var(--ds-text-md)/1.5 var(--ds-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--ds-text-sm); margin-top:var(--ds-space-3); min-height:20px; color:var(--ds-muted); }
.ds .ds-surface { border:1px solid var(--ds-border); border-radius:var(--ds-radius); background:var(--ds-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--ds-shadow); border-color:#ffffff; }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--ds-inset); background:var(--ds-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--ds-high); box-shadow:0 8px 24px #38465e12; }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--ds-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--ds-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds .ds-choices { display:grid; grid-template-columns:repeat(auto-fit,minmax(min(100%,170px),1fr)); gap:var(--ds-space-6); }
.ds .ds-choices fieldset,.ds .ds-radio-group { border:0; padding:0; min-width:0; }
.ds .ds-choices legend,.ds .ds-radio-group legend { font-size:14px; font-weight:600; margin-bottom:var(--ds-space-3); padding:0; }
.ds .ds-choice { display:flex; align-items:center; gap:var(--ds-space-3); min-height:44px; width:fit-content; padding-inline:4px; cursor:pointer; font-size:14px; }
.ds .ds-choice input { appearance:none; position:relative; margin:0; width:22px; height:22px; border:1.5px solid var(--ds-control-border); border-radius:7px; background:var(--ds-bg); box-shadow:var(--ds-inset); cursor:inherit; flex-shrink:0; }
.ds .ds-choice input:checked,.ds .ds-choice input:indeterminate { background:var(--ds-accent); border-color:var(--ds-accent); box-shadow:none; }
.ds .ds-choice input[type="checkbox"]:checked::after { content:''; position:absolute; width:6px; height:10px; left:6px; top:2px; border:solid #fff; border-width:0 2px 2px 0; transform:rotate(45deg); }
.ds .ds-choice input:indeterminate::after { content:''; position:absolute; width:10px; height:2px; left:4px; top:8px; background:#fff; transform:none; border:0; }
.ds .ds-choice input[type="radio"] { border-radius:50%; }
.ds .ds-choice input[type="radio"]:checked::after { content:''; position:absolute; inset:5px; background:#fff; border-radius:50%; }
.ds .ds-choice:has(:disabled) { color:var(--ds-muted); cursor:not-allowed; }
.ds .ds-choice input:disabled { opacity:1; background:var(--ds-disabled); border-color:var(--ds-border); box-shadow:none; }
.ds .ds-choice input:disabled::after { border-color:var(--ds-muted); }
.ds .ds-choice input[type="radio"]:disabled::after { background:var(--ds-muted); }
.ds .ds-choice .ds-switch { width:44px; height:26px; border-radius:24px; }
.ds .ds-switch::before { content:''; position:absolute; top:3px; left:3px; width:18px; height:18px; border-radius:50%; background:var(--ds-muted); box-shadow:0 1px 3px #26344726; transition:left var(--ds-duration); }
.ds .ds-choice input.ds-switch:checked::after { content:none; }
.ds .ds-switch:checked::before { left:21px; background:#fff; }
.ds .ds-switch:disabled::before { background:var(--ds-muted); box-shadow:none; }
@media(forced-colors:active) {
  .ds .ds-choice input:not(.ds-switch) { appearance:auto; }
  .ds .ds-choice input:not(.ds-switch)::after { display:none; }
  .ds .ds-switch { border-color:ButtonText; }
  .ds .ds-switch::before { background:ButtonText; }
  .ds .ds-switch:checked { background:Highlight; }
  .ds .ds-switch:checked::before { background:HighlightText; }
}
/* looks: checkbox, radio and switch share the label hook .ds-choice[data-look]; checked keeps a mark or a moved thumb, never color alone */
.ds .ds-choice[data-look="round"] input { border-radius:50%; }
.ds .ds-choice[data-look="round"] input[type="checkbox"]:checked::after { left:6.5px; top:3px; }
.ds .ds-choice[data-look="outline"] input { border-width:2px; }
.ds .ds-choice[data-look="outline"] input:is(:checked,:indeterminate) { background:var(--ds-bg); border-color:var(--ds-accent); }
.ds .ds-choice[data-look="outline"] input[type="checkbox"]:checked::after { left:5.5px; top:1.5px; border-color:var(--ds-accent); }
.ds .ds-choice[data-look="outline"] input:indeterminate::after { left:3.5px; top:7.5px; background:var(--ds-accent); }
.ds .ds-choice[data-look="outline"] input[type="radio"]:checked::after { inset:4px; background:var(--ds-accent); }
.ds .ds-choice[data-look="check"] input[type="radio"]:checked::after { inset:auto; left:7px; top:3px; width:5px; height:10px; border:solid var(--ds-on-accent); border-width:0 2px 2px 0; border-radius:0; background:transparent; transform:rotate(45deg); }
.ds .ds-choice[data-look="card"] { min-width:200px; min-height:56px; padding:12px 16px; border:1px solid var(--ds-border); border-radius:var(--ds-control-radius); background:var(--ds-bg); }
.ds .ds-choice[data-look="card"]:has(:checked) { border-color:var(--ds-accent); box-shadow:inset 0 0 0 1px var(--ds-accent); background:var(--ds-high); font-weight:600; }
.ds .ds-radio-group:has(> .ds-choice[data-look="card"]) .ds-choice + .ds-choice { margin-top:var(--ds-space-2); }
.ds .ds-choice[data-look="chip"] { gap:6px; min-height:44px; padding:8px 16px; border:1px solid var(--ds-control-border); border-radius:99px; background:var(--ds-bg); }
.ds .ds-choice[data-look="chip"] input { width:0; height:18px; border:0; background:transparent; box-shadow:none; }
.ds .ds-choice[data-look="chip"]:has(:focus-visible) { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ds-choice[data-look="chip"]:has(:checked) { padding-left:12px; border-color:var(--ds-accent); background:var(--ds-accent); color:var(--ds-on-accent); }
.ds .ds-choice[data-look="chip"] input:checked { width:18px; background:transparent; }
.ds .ds-choice[data-look="chip"] input[type="checkbox"]:checked::after { left:6px; top:1px; border-color:var(--ds-on-accent); }
.ds .ds-choice[data-look="list"] { width:100%; flex-direction:row-reverse; justify-content:space-between; min-height:52px; padding:12px 4px; border-block:1px solid var(--ds-border); }
.ds .ds-radio-group:has(> .ds-choice[data-look="list"]) .ds-choice + .ds-choice { border-top:0; }
.ds .ds-choice[data-look="neumorph"] input { background:var(--ds-surface); box-shadow:var(--ds-raised); }
.ds .ds-choice[data-look="neumorph"] input:is(:checked,:indeterminate) { border-color:transparent; background:var(--ds-surface); box-shadow:var(--ds-inset); }
.ds .ds-choice[data-look="neumorph"] input[type="checkbox"]:checked::after { border-color:var(--ds-accent); }
.ds .ds-choice[data-look="neumorph"] input:indeterminate::after,.ds .ds-choice[data-look="neumorph"] input[type="radio"]:checked::after { background:var(--ds-accent); }
.ds .ds-radio-group:has(> .ds-choice[data-look="segment"]) { display:flex; flex-wrap:wrap; }
.ds .ds-radio-group:has(> .ds-choice[data-look="segment"]) > legend { width:100%; }
.ds .ds-choice[data-look="segment"] { position:relative; gap:6px; min-height:44px; margin:0; padding:10px 18px; border:1px solid var(--ds-control-border); background:var(--ds-bg); }
.ds .ds-choice[data-look="segment"] + .ds-choice[data-look="segment"] { margin-left:-1px; }
.ds .ds-choice[data-look="segment"]:first-of-type { border-radius:12px 0 0 12px; }
.ds .ds-choice[data-look="segment"]:last-of-type { border-radius:0 12px 12px 0; }
.ds .ds-choice[data-look="segment"] input { position:absolute; inset:0; width:100%; height:100%; opacity:0; }
.ds .ds-choice[data-look="segment"]:has(:checked) { z-index:1; border-color:var(--ds-accent); background:var(--ds-accent); color:var(--ds-on-accent); font-weight:600; }
.ds .ds-choice[data-look="segment"]:has(:checked)::before { content:'✓'; content:'✓' / ''; }
.ds .ds-choice[data-look="segment"]:has(:focus-visible) { z-index:2; outline:3px solid var(--ds-focus); outline-offset:2px; }
.ds .ds-choice[data-look="ios"] .ds-switch { width:51px; height:31px; border:0; border-radius:99px; background:color-mix(in oklab,var(--ds-control-border) 45%,var(--ds-bg)); box-shadow:none; }
.ds .ds-choice[data-look="ios"] .ds-switch::before { top:2px; left:2px; width:27px; height:27px; background:var(--ds-bg); box-shadow:0 3px 8px color-mix(in oklab,var(--ds-text) 24%,transparent); }
.ds .ds-choice[data-look="ios"] .ds-switch:checked { background:var(--ds-success); }
.ds .ds-choice[data-look="ios"] .ds-switch:checked::before { left:22px; background:var(--ds-bg); }
.ds .ds-choice[data-look="slim"] .ds-switch { width:36px; height:14px; margin-inline:4px; border:0; background:color-mix(in oklab,var(--ds-control-border) 45%,var(--ds-bg)); box-shadow:none; overflow:visible; }
.ds .ds-choice[data-look="slim"] .ds-switch::before { top:-4px; left:-4px; width:22px; height:22px; background:var(--ds-bg); box-shadow:0 1px 4px color-mix(in oklab,var(--ds-text) 35%,transparent); }
.ds .ds-choice[data-look="slim"] .ds-switch:checked { background:color-mix(in oklab,var(--ds-accent) 45%,var(--ds-bg)); }
.ds .ds-choice[data-look="slim"] .ds-switch:checked::before { left:18px; background:var(--ds-accent); }
.ds .ds-choice[data-look="text"] .ds-switch { width:64px; height:30px; }
.ds .ds-choice[data-look="text"] .ds-switch::before { width:22px; height:22px; top:2.5px; left:3px; }
.ds .ds-choice[data-look="text"] .ds-switch:checked::before { left:36px; }
.ds .ds-choice[data-look="text"] input.ds-switch::after,.ds .ds-choice[data-look="text"] input.ds-switch:checked::after { content:'끔'; content:'끔' / ''; position:absolute; top:50%; left:auto; right:9px; width:auto; height:auto; border:0; transform:translateY(-50%); color:var(--ds-muted); font-size:11px; font-weight:700; line-height:1; }
.ds .ds-choice[data-look="text"] input.ds-switch:checked::after { content:'켬'; content:'켬' / ''; left:10px; right:auto; color:var(--ds-on-accent); }
.ds .ds-choice[data-look="square"] .ds-switch { width:48px; height:28px; border-radius:7px; }
.ds .ds-choice[data-look="square"] .ds-switch::before { width:20px; height:20px; border-radius:4px; }
.ds .ds-choice[data-look="square"] .ds-switch:checked::before { left:22px; }
.ds .ds-choice[data-look="outline"] .ds-switch { width:52px; height:32px; border:2px solid var(--ds-control-border); border-radius:99px; background:var(--ds-surface); box-shadow:none; }
.ds .ds-choice[data-look="outline"] .ds-switch::before { top:6px; left:6px; width:16px; height:16px; background:var(--ds-control-border); box-shadow:none; transition:left var(--ds-duration),width var(--ds-duration),height var(--ds-duration),top var(--ds-duration); }
.ds .ds-choice[data-look="outline"] .ds-switch:checked { border-color:var(--ds-accent); background:var(--ds-accent); }
.ds .ds-choice[data-look="outline"] .ds-switch:checked::before { top:2px; left:22px; width:24px; height:24px; background:var(--ds-on-accent); }
.ds .ds-choice[data-look="neumorph"] .ds-switch { width:52px; height:30px; border:1px solid var(--ds-control-border); border-radius:99px; background:var(--ds-surface); box-shadow:var(--ds-inset); }
.ds .ds-choice[data-look="neumorph"] .ds-switch::before { top:2px; left:2px; width:24px; height:24px; background:var(--ds-surface); box-shadow:var(--ds-raised); }
.ds .ds-choice[data-look="neumorph"] .ds-switch:checked { background:var(--ds-soft); box-shadow:var(--ds-inset); }
.ds .ds-choice[data-look="neumorph"] .ds-switch:checked::before { left:24px; background:var(--ds-accent); }
.ds .ds-choice[data-look]:has(:disabled) input:disabled { background:var(--ds-disabled); border-color:var(--ds-border); box-shadow:none; }
.ds .ds-choice[data-look]:has(:disabled) input:disabled::after { border-color:var(--ds-muted); color:var(--ds-muted); }
.ds .ds-choice[data-look]:has(:disabled) input:is([type="radio"],:indeterminate):disabled::after { background:var(--ds-muted); }
.ds .ds-choice[data-look]:has(:disabled) input.ds-switch:disabled::before { background:var(--ds-muted); box-shadow:none; }
.ds .ds-choice:is([data-look="chip"],[data-look="segment"],[data-look="card"]):has(:disabled) { border-color:var(--ds-border); background:var(--ds-disabled); color:var(--ds-muted); box-shadow:none; }

